import React, { useEffect, useState } from 'react';
import { createTm } from '../services/api';

export default function NewMachineCreate({ onCreated, onCancel }) {
  const [serial, setSerial] = useState('');
  const [model, setModel] = useState('');
  // выпадашки
  const [customers, setCustomers] = useState([]); // [{ id, name }]
  const [serviceCompanies, setServiceCompanies] = useState([]); // [{ id, name }]
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [selectedServiceCompanyId, setSelectedServiceCompanyId] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // подгружать данные для выпадашек
  useEffect(() => {
    // меняйте пути под ваши endpoints, если они другие
    fetch('/api/customers/')
      .then(res => res.json())
      .then(data => setCustomers(Array.isArray(data) ? data : []))
      .catch(() => setCustomers([]));

    fetch('/api/service_companies/')
      .then(res => res.json())
      .then(data => setServiceCompanies(Array.isArray(data) ? data : []))
      .catch(() => setServiceCompanies([]));
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    const payload = {
      serial_number_machine: serial,
      model_machine: model,
      // отправляем ID выбранного элемента или null
      customer: selectedCustomerId || null,
      service_company: selectedServiceCompanyId || null,
    };
    try {
      const res = await createMachine(payload);
      setLoading(false);
      onCreated?.(res);
    } catch (err) {
      setLoading(false);
      setError(err?.message || 'Ошибка при создании');
    }
  };

  return (
    <div className="new-machine-create" style={{ border: '1px solid #ccc', padding: 16, borderRadius: 6, margin: '12px 0' }}>
      <h3>Создать новую машину</h3>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <input placeholder="Серийный номер" value={serial} onChange={(e) => setSerial(e.target.value)} required />
        <input placeholder="Модель машины" value={model} onChange={(e) => setModel(e.target.value)} required />

        <select value={selectedCustomerId} onChange={(e) => setSelectedCustomerId(e.target.value)}>
          <option value="">Выберите клиента</option>
          {customers.map((c) => (
            <option key={c.id} value={c.id}>{c.name}</option>
          ))}
        </select>

        <select value={selectedServiceCompanyId} onChange={(e) => setSelectedServiceCompanyId(e.target.value)}>
          <option value="">Выберите сервисную компанию</option>
          {serviceCompanies.map((s) => (
            <option key={s.id} value={s.id}>{s.name}</option>
          ))}
        </select>

        <div style={{ display: 'flex', gap: 8 }}>
          <button type="submit" disabled={loading}>{loading ? 'Создание...' : 'Создать'}</button>
          <button type="button" onClick={onCancel} disabled={loading}>Отмена</button>
        </div>
        {error && <div style={{ color: 'red' }}>{error}</div>}
      </form>
    </div>
  );
}
